Q: Is it possible to define a non empty array type in Typescript? A: <p>What about this?</p>
<pre><code>declare const nonEmptyArrayBrand: unique symbol;

export type NonEmptyArray&lt;T&gt; = T[] &amp; {
  readonly 0: T;
  readonly [nonEmptyArrayBrand]: true;
};

export function isNonEmptyArray&lt;T&gt;(values: T[]): values is NonEmptyArray&lt;T&gt; {
  return values.length &gt; 0;
}
</code></pre>
